"""Exercise diagnostic transport on disposable scripted fixtures only."""
from pathlib import Path
from tempfile import TemporaryDirectory
import shutil,json
from ops_i11 import Study,DEFAULT_ROOT,BASE,read,write,digest,now

def hashes(root):return {p.relative_to(root).as_posix():digest(p.read_bytes()) for p in root.rglob('*') if p.is_file()}
before=hashes(DEFAULT_ROOT);checks=[]
def check(value,label):
    assert value,label
    checks.append(label)
def blocked(fn,word):
    try:fn()
    except AssertionError as e:check(word in str(e),str(e))
    else:raise AssertionError('Missing guard '+word)

with TemporaryDirectory(prefix='ops-i11-fixture-') as temp:
    root=Path(temp)/'study';shutil.copytree(DEFAULT_ROOT,root)
    s=Study(root,True);s.verify()
    blocked(lambda:s.before('d02','spawn'),'Frozen first-invocation order')
    for spec in s.plan['runs']:
        name=spec['name'];p=root/name
        count=3 if name=='d01' else 2 if name=='d02' else 1
        for i in range(count):
            c=s.before(name,'spawn' if i==0 else 'fileless_retry');s.bind(c['id'],c['participant'])
            if name=='d01' or name=='d02' and i==0:pass
            elif name=='d03':(p/'output.json').write_text('{',encoding='utf8')
            elif name=='d04':write(p/'output.json',[1,2])
            else:
                response=read(p/'expected.json')
                if name=='d05':response.pop('internal_total')
                if name=='d06':response.update(internal_first_account=True)
                write(p/'output.json',response)
            s.finish(c['id'],'scripted fixture reply')
        blocked(lambda:s.before(name,'fileless_retry'),'Assignment already accounted')
    report=s.audit()
    check(report['subject_invocations']==19,'19synthetic turns')
    check(report['json_submissions']==15 and report['fileless_invocations']==4,'JSON and fileless separate')
    rows=read(root/'audit.json')['rows'];states={x['condition']['name']:x['provenance'] for x in rows}
    check(states['d01']['status']=='transport_failure','retain fileless failure')
    check(states['d03']['status']==states['d04']['status']=='invalid_response','malformed and scalar responses retained without coaching')
    check(states['d05']['grade']['correct']==19,'missing field scored within submitted object')
    check(not states['d06']['cost_orderings']['scorable'],'bool is not dollar amount')
    check(sum(x['fully_correct'] for x in report['groups'].values())==11,'allassignments retained with eleven correct fixtures')
check(before==hashes(DEFAULT_ROOT),'live prepared inputs and zero-call ledger unchanged')
write(BASE/'i11-operations-transport-validation.json',dict(passed=True,utc=now(),model_subjects=0,checks=checks,fixture_report=report,
    source_sha256=digest(Path(__file__).with_name('ops_i11.py').read_bytes()),live_files_unchanged=len(before)))
print(json.dumps(dict(passed=True,checks=len(checks),live_files_unchanged=len(before),fixture_report=report)))

